import assert from 'node:assert/strict';
import {test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {traceSummary} from '../src/plugins/index.ts';

test('end-to-end trace propagation through handle stages', () => {
  const job = {requestId: 'job-999', name: 'background-task'};
  const result = handle('trace-abc', 'user-123', job);

  // Context construction
  assert.equal(result.context.traceId, 'trace-abc');
  assert.equal(result.context.userId, 'user-123');
  assert.equal('requestId' in result.context, false);

  // Middleware headers propagation
  assert.deepEqual(result.headers, {'x-request-id': 'trace-abc'});

  // Logging output keys
  assert.deepEqual(result.logs, {requestId: 'trace-abc', userId: 'user-123'});

  // Response wire keys and payload
  assert.equal(result.body.requestId, 'trace-abc');
  assert.deepEqual(result.body.payload, {
    requestId: 'job-999',
    trace: 'trace-abc/worker',
    audit: 'job:job-999',
    name: 'background-task',
  });
});

test('unrelated Job identifier remains intact and independent of traceId', () => {
  const job = {requestId: 'distinct-job-id', name: 'sync-data'};
  const result = handle('distinct-trace-id', 'user-456', job);

  // Job requestId is preserved on payload output
  assert.equal(result.body.payload.requestId, 'distinct-job-id');
  assert.equal(result.body.payload.audit, 'job:distinct-job-id');

  // Trace identifier is properly suffixed for worker stage
  assert.equal(result.body.payload.trace, 'distinct-trace-id/worker');
  assert.notEqual(result.body.payload.requestId, result.context.traceId);
});

test('forkContext non-mutation and suffix propagation', () => {
  const root = createContext('root-trace', 'user-789');
  const forked = forkContext(root, 'child');

  assert.equal(root.traceId, 'root-trace');
  assert.equal('requestId' in root, false);
  assert.equal(forked.traceId, 'root-trace/child');
  assert.equal(forked.userId, 'user-789');
  assert.equal('requestId' in forked, false);
});

test('traceSummary and plugin propagation', () => {
  const context = createContext('plugin-trace', 'user-plugin');
  const summary = traceSummary(context);

  assert.equal(summary.length, 8);
  for (let i = 0; i < 8; i++) {
    assert.deepEqual(summary[i], {
      requestId: 'plugin-trace',
      tag: `plugin${i}`,
      user: 'user-plugin',
    });
  }
});
